function uuidv4() {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, c => {
    const r = Math.random() * 16 | 0;
    const v = c === 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

function safeStr(v) {
  return (v === null || v === undefined) ? "" : String(v);
}

try {
  const trace_id = uuidv4();
  const t0 = Date.now();

  const msg = $json?.message ?? {};
  const chat_id = msg?.chat?.id ?? null;
  const user_id = msg?.from?.id ?? "unknown";
  const text = msg?.text ?? "";

  return [{
    json: {
      meta: {
        request_id: trace_id,
        ts: new Date().toISOString(),
        channel: "telegram",
        chat_id: chat_id ? Number(chat_id) : null
      },
      input: {
        user_id: safeStr(user_id),
        question: safeStr(text).trim()
      },
      telegram: $json,
      retrieval: { top_k: 5, hits: [], top_score: null },
      decision: { mode: "ALLOW", reason: "day1_stub" },
      output: { answer: "", sources: [] },
      error: null,
      timers: { t_start_ms: t0 }
    }
  }];
} catch (e) {
  const trace_id = uuidv4();
  return [{
    json: {
      meta: {
        request_id: trace_id,
        ts: new Date().toISOString(),
        channel: "telegram",
        prompt_version: "v1",
        chat_model: "day1_stub",
        embedding_model: "n/a",
        chat_id: null
      },
      input: { user_id: "unknown", question: "" },
      telegram: $json,
      retrieval: { top_k: 0, hits: [], top_score: null },
      decision: { mode: "DENY", reason: "build_envelope_error" },
      output: { answer: `⚠️ Sorry — something went wrong. Trace ID: ${trace_id}`, sources: [] },
      error: {
        message: e?.message || "build_envelope_error",
        node: "Build Envelope",
        stack: e?.stack || null
      },
      timers: { t_start_ms: Date.now() }
    }
  }];
}

return items.map(item => {
  const j = item.json || {};

  const helpHtml =
`<b>KB RAG Assistant (demo)</b>

<b>What you get</b>
• <b>Digest</b> of the latest captured posts + <b>source links</b>
• <b>Q&amp;A</b> that answers <b>only from those sources</b> (no guessing)
• Top signals are marked: 🚨 / ⚠️ / 💤

<b>How to use</b>
1) <code>/start &lt;invite_token&gt;</code> — enable demo
2) <code>/digest</code> — show digest

<b>Invite token / questions</b>
For an invite token or any questions about this bot, message <b>@arseniy_ostroumov</b>.

<b>Then ask a question</b>, for example:
• What are the key updates on <code>$Whalentine</code>?
• Summarize the claim about altcoins breaking the downtrend vs <code>BTC</code>.
• What does “survival is the alpha” mean here?

<b>Note</b>
If the answer isn’t in the sources, I’ll say <b>I can’t answer from the KB</b>.`;

  return {
    json: {
      ...j,

      // ❗ retrieval НЕ трогаем для команд
      retrieval: j.retrieval ?? null,
      error: j.error ?? null,

      decision: {
        ...(j.decision || {}),
        mode: "COMMAND",
        reason: "help"
      },

      output: {
        ...(j.output || {}),
        answer: helpHtml,
        sources: [],
        parse_mode: "HTML"
      }
    }
  };
});

const j = $json ?? {};

function genId() {
  if (globalThis.crypto?.randomUUID) return globalThis.crypto.randomUUID();
  return `rid_${Date.now()}_${Math.random().toString(16).slice(2)}`;
}

function isObj(x) {
  return x !== null && typeof x === "object" && !Array.isArray(x);
}

const meta = isObj(j.meta) ? j.meta : {};
const request_id = meta.request_id ?? j.request_id ?? genId();
const trace_id = j.trace_id ?? meta.trace_id ?? meta.request_id ?? request_id;

const telegram = isObj(j.telegram) ? j.telegram : {};
const input = isObj(j.input) ? j.input : {};
const output = isObj(j.output) ? j.output : {};

// Telegram message/callback extraction
const tgMsg =
  telegram.message ??
  telegram.callback_query?.message ??
  {}; // may be {}

const tgFrom =
  telegram.message?.from ??
  telegram.callback_query?.from ??
  null;

// IDs (cover all known shapes)
const chat_id =
  j.chat_id ??
  j.tg_chat_id ??
  input.chat_id ??
  input.tg_chat_id ??
  telegram.chat?.id ??
  telegram.message?.chat?.id ??
  telegram.callback_query?.message?.chat?.id ??
  tgMsg.chat?.id ??
  null;

const user_id =
  j.user_id ??
  j.tg_user_id ??
  input.user_id ??
  input.tg_user_id ??
  telegram.from?.id ??
  telegram.message?.from?.id ??
  telegram.callback_query?.from?.id ??
  tgFrom?.id ??
  null;

// Question / Reply text (always strings)
const questionRaw =
  input.question ??
  input.text ??
  j.question ??
  j.text ??
  tgMsg.text ??
  telegram.callback_query?.data ??
  "";

const replyTextRaw =
  output.reply_text ??
  output.reply ??
  j.reply_text ??
  j.reply ??
  j.answer ??
  output.answer ??
  "";

const question = String(questionRaw ?? "");
const reply_text = String(replyTextRaw ?? "");

return [{
  json: {
    trace_id,
    chat_id: chat_id == null ? null : String(chat_id),
    user_id: user_id == null ? null : String(user_id),

    meta: { ...meta, request_id },

    input: { ...input, question },
    telegram,

    decision: j.decision ?? null,
    output: { ...output, reply_text },

    retrieval: j.retrieval ?? null,
    timers: j.timers ?? null,
    error: j.error ?? null,

    channel: j.channel ?? meta.channel ?? "unknown",
  }
}];

const j = $json ?? {};
const chat_id = Number(j.telegram?.message?.chat?.id ?? j.meta?.chat_id ?? j.chat_id ?? 0);

// только твой приватный чат для демо (замени/добавь нужные id)
const DEMO_CHAT_IDS = new Set([168487641]);

const forced = DEMO_CHAT_IDS.has(chat_id) ? "ceo_x_demo" : null;
const kb_ref = forced ?? (j.kb_ref ?? j.meta?.kb_ref ?? null);

return [{
  json: {
    ...j,
    kb_ref,
    meta: {
      ...(j.meta ?? {}),
      kb_ref,
      chat_id: Number.isFinite(chat_id) ? chat_id : (j.meta?.chat_id ?? null),
    },
  }
}];

// Digest builder (Telegram HTML) — FINAL
// Applies requested changes:
// 1) Hide section like tweet_08/tweet_09 completely (no section shown)
// 2) Different numbering: Top #1..#3, Feed #1..
// 3) Skip "Other" block if content empty/too short
// 4) Ticker label: if tickers>3 => [MULTI], else show up to 2 tickers [$BTC,$ETH], else none
// 5) Stricter 🚨: only if text contains "🚨" OR keywords broke/break/downtrend/capitulation
//    else ⚠️ if "watch" keywords, else 💤
// 6) Short TL;DR: Coverage top-2 + +N, Tickers top-4
// Plus: unified link style, separators, selective bold.

const rows = (items ?? []).map(i => i?.json).filter(Boolean);

const chat_id =
  $json?.chat_id ??
  $json?.meta?.chat_id ??
  $json?.telegram?.message?.chat?.id ??
  null;

function escHtml(s) {
  if (s === null || s === undefined) return "";
  return String(s)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

function normDoc(doc) {
  const d = (doc ?? "").toString().trim();
  if (!d || d.toLowerCase() === "unknown") return "Other";
  return d;
}

function snip(s, n = 160) {
  if (s === null || s === undefined) return "";
  const t = String(s).replace(/\s+/g, " ").trim();
  return t.length > n ? t.slice(0, n - 1) + "…" : t;
}

function parseDateMs(v) {
  if (!v) return null;
  const ms = Date.parse(String(v));
  return Number.isFinite(ms) ? ms : null;
}

function fmtUTC(ms) {
  const d = new Date(ms);
  const hh = String(d.getUTCHours()).padStart(2, "0");
  const mm = String(d.getUTCMinutes()).padStart(2, "0");
  return `${hh}:${mm} UTC`;
}

function extractTickers(text) {
  if (!text) return [];
  const m = String(text).match(/\$[A-Za-z0-9_]{2,12}/g);
  if (!m) return [];
  const seen = new Set();
  const out = [];
  for (const t of m) {
    const k = t.toUpperCase();
    if (!seen.has(k)) { seen.add(k); out.push(k); }
  }
  return out;
}

function tickerBadge(text) {
  const ts = extractTickers(text);
  if (!ts.length) return ""; // no badge
  if (ts.length > 3) return "MULTI";
  const shown = ts.slice(0, 2);
  return shown.join(",");
}

// Stricter importance heuristic (no LLM)
function signalTag(text) {
  const t = (text ?? "").toString().toLowerCase();

  // 🚨 only if explicit siren or strong keywords
  const hi = ["🚨", "broke", "break", "downtrend", "capitulation"];
  if (hi.some(k => t.includes(k))) return "🚨";

  // ⚠️ watchlist-ish
  const mid = ["unpopular", "opinion", "i think", "isn't done", "maybe", "study this", "watch", "seems", "looks"];
  if (mid.some(k => t.includes(k))) return "⚠️";

  return "💤";
}

function weight(tag) {
  return tag === "🚨" ? 2 : tag === "⚠️" ? 1 : 0;
}

function keyFor(e) {
  // for dedupe: prefer url, else doc+section
  if (e.url) return `url:${e.url}`;
  return `ds:${e.doc}::${e.section}`;
}

const SEP = "────────────";

if (!rows.length) {
  return [{
    json: {
      chat_id,
      parse_mode: "HTML",
      reply_text:
        `🧾 <b>Digest</b>\n${SEP}\n` +
        `No chunks yet. Send <code>/demo</code> to load demo feed.`,
    }
  }];
}

// Enrich
const enriched = rows.map(r => {
  const doc = normDoc(r?.doc);
  const section = (r?.section ?? "chunk").toString();
  const url = r?.source_url ? String(r.source_url) : "";
  const content = r?.content ?? "";
  const tag = signalTag(content);
  const created_ms = parseDateMs(r?.created_at);
  const badge = tickerBadge(content); // "MULTI" or "$BTC,$ETH" or ""
  return { r, doc, section, url, content, tag, created_ms, badge, k: null };
});

// Recency
const maxMs = enriched.reduce((acc, x) => {
  if (x.created_ms === null) return acc;
  return acc === null ? x.created_ms : Math.max(acc, x.created_ms);
}, null);

// Coverage by doc
const cov = new Map();
for (const e of enriched) cov.set(e.doc, (cov.get(e.doc) ?? 0) + 1);
const covPairs = Array.from(cov.entries()).sort((a, b) => b[1] - a[1]);
const covTop2 = covPairs.slice(0, 2).map(([d, n]) => `${d}=${n}`);
const covMore = Math.max(0, covPairs.length - 2);

// Top tickers (for TL;DR): top-4
const allTickers = [];
for (const e of enriched) allTickers.push(...extractTickers(e.content));
const topTickers = (() => {
  const c = new Map();
  for (const t of allTickers) c.set(t, (c.get(t) ?? 0) + 1);
  return Array.from(c.entries())
    .sort((a, b) => b[1] - a[1])
    .slice(0, 4)
    .map(([t, n]) => `${t}(${n})`);
})();

// Signals counts
let cHi = 0, cMid = 0, cLow = 0;
for (const e of enriched) {
  if (e.tag === "🚨") cHi++;
  else if (e.tag === "⚠️") cMid++;
  else cLow++;
}

// Top signals: best by weight then newest
const topSignals = enriched
  .slice()
  .sort((a, b) => (weight(b.tag) - weight(a.tag)) || ((b.created_ms ?? -1) - (a.created_ms ?? -1)))
  .slice(0, 3);

const topKeys = new Set(topSignals.map(e => keyFor(e)));

// Group by doc
const byDoc = new Map();
for (const e of enriched) {
  if (!byDoc.has(e.doc)) byDoc.set(e.doc, []);
  byDoc.get(e.doc).push(e);
}

// Doc order: Other last
const docsOrdered = Array.from(byDoc.keys()).sort((a, b) => {
  if (a === "Other") return 1;
  if (b === "Other") return -1;
  return (byDoc.get(b)?.length ?? 0) - (byDoc.get(a)?.length ?? 0);
});

// Sort within doc: importance desc, then newest desc
for (const doc of docsOrdered) {
  byDoc.get(doc).sort((a, b) => {
    const dw = weight(b.tag) - weight(a.tag);
    if (dw) return dw;
    return (b.created_ms ?? -1) - (a.created_ms ?? -1);
  });
}

// Helper: render badge
function renderBadge(badge) {
  if (!badge) return "";
  if (badge === "MULTI") return ` <b>[</b><code>MULTI</code><b>]</b>`;
  return ` <b>[</b><code>${escHtml(badge)}</code><b>]</b>`;
}

// Build output
let out =
  `🧾 <b>Digest</b> <i>(last ${enriched.length} chunks)</i>\n` +
  `${SEP}\n`;

out += `<b>Signals:</b> 🚨 ${cHi} · ⚠️ ${cMid} · 💤 ${cLow}`;
if (maxMs !== null) out += ` · <b>last:</b> <code>${escHtml(fmtUTC(maxMs))}</code>`;
out += `\n`;

if (covTop2.length) {
  out += `<b>Coverage:</b> <code>${escHtml(covTop2.join("  "))}${covMore ? `  +${covMore}` : ""}</code>\n`;
}
if (topTickers.length) {
  out += `<b>Tickers:</b> <code>${escHtml(topTickers.join("  "))}</code>\n`;
}

out += `${SEP}\n🔥 <b>Top signals</b>\n`;

// Render Top signals (short snippet, no section shown)
let tIdx = 1;
for (const e of topSignals) {
  const badge = renderBadge(e.badge);
  const head = `${e.tag} <b>Top #${tIdx}</b>${badge} <i>${escHtml(e.doc)}</i>`;
  out += `\n${head}\n${escHtml(snip(e.content, 110))}`;
  if (e.url) out += `\n<a href="${escHtml(e.url)}">🔗 ${escHtml(e.doc)}</a>`;
  out += `\n`;
  tIdx++;
}

out += `\n${SEP}\n`;

// Full digest (skip duplicates, hide Other if empty/too short)
let fIdx = 1;
const LIMIT = 12;

for (const doc of docsOrdered) {
  const arr = byDoc.get(doc) ?? [];

  // skip top duplicates
  const visible = arr.filter(e => !topKeys.has(keyFor(e)));

  // Special handling: Other — hide if content empty/short
  let filtered = visible;
  if (doc === "Other") {
    filtered = visible.filter(e => snip(e.content, 40).length >= 20); // drop empty-ish
    if (!filtered.length) continue;
  } else {
    if (!filtered.length) continue;
  }

  out += `<b>${escHtml(doc)}</b> <i>(${filtered.length})</i>\n`;

  for (const e of filtered) {
    const badge = renderBadge(e.badge);

    out += `\n${e.tag} <b>Feed #${fIdx}</b>${badge}\n${escHtml(snip(e.content, 170))}`;
    if (e.url) out += `\n<a href="${escHtml(e.url)}">🔗 ${escHtml(doc)}</a>`;
    out += `\n`;

    fIdx++;
    if (fIdx > LIMIT) break;
  }

  out += `\n`;
  if (fIdx > LIMIT) break;
}

return [{
  json: {
    chat_id,
    parse_mode: "HTML",
    reply_text: out,
  }
}];
